const fs = require('fs');
const path = require('path');

const DEFAULTS = {
  port: 3000,
  host: '127.0.0.1',
};

const baseDir = __dirname;
const inputPath = path.join(baseDir, 'config.json');
const outputPath = path.join(baseDir, 'config.out.json');

function loadConfig(file) {
  let raw;
  try {
    raw = fs.readFileSync(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return {};
    throw err;
  }
  const trimmed = raw.trim();
  if (!trimmed) return {};
  const parsed = JSON.parse(trimmed);
  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new TypeError('config.json must contain a JSON object');
  }
  return parsed;
}

function withDefaults(config) {
  const result = { ...config };
  for (const [key, value] of Object.entries(DEFAULTS)) {
    if (result[key] === undefined || result[key] === null) {
      result[key] = value;
    }
  }
  return result;
}

function main() {
  const config = loadConfig(inputPath);
  const output = withDefaults(config);
  fs.writeFileSync(outputPath, `${JSON.stringify(output, null, 2)}\n`, 'utf8');
  console.log(`wrote ${path.basename(outputPath)}: ${JSON.stringify(output)}`);
}

try {
  main();
} catch (err) {
  console.error(`check failed: ${err.message}`);
  process.exitCode = 1;
}

